#!/usr/bin/env python3
"""TestFlight: son derlemeyi bekle, dış test grubunu kur, testçileri ekle, derlemeyi ver, Beta incelemesine gönder."""
import os, time, jwt, requests
B='https://api.appstoreconnect.apple.com/v1'
APP=os.environ['APP_ID']; GRUP='Mr. Anduv! Testçileri'
def H():
    t=jwt.encode({'iss':os.environ['ASC_ISSUER_ID'],'iat':int(time.time()),'exp':int(time.time())+900,'aud':'appstoreconnect-v1'},os.environ['P8'],algorithm='ES256',headers={'kid':os.environ['ASC_KEY_ID'],'typ':'JWT'})
    return {'Authorization':'Bearer '+t,'Content-Type':'application/json'}
def get(p,**q):
    r=requests.get(B+p,headers=H(),params=q); r.raise_for_status(); return r.json()
def post(p,body):
    r=requests.post(B+p,headers=H(),json=body)
    if r.status_code>=400: print('!',p,r.status_code,r.text[:600])
    return r
def patch(p,body):
    r=requests.patch(B+p,headers=H(),json=body)
    if r.status_code>=400: print('!',p,r.status_code,r.text[:600])
    return r
# 1) son derleme işlensin
build=None
MIN=int(os.environ.get('MIN_BUILD') or (open('store/DERLEME').read().strip() if os.path.exists('store/DERLEME') else 0) or 0)
print('beklenen derleme no ≥',MIN)
for i in range(70):
    d=get('/builds',**{'filter[app]':APP,'sort':'-uploadedDate','limit':1})['data']
    if d and int(d[0]['attributes']['version'])<MIN: print('derleme',MIN,'henüz görünmüyor'); time.sleep(60); continue
    if d:
        st=d[0]['attributes']['processingState']; print('derleme',d[0]['attributes']['version'],st)
        if st=='VALID': build=d[0]; break
        if st in ('FAILED','INVALID'): raise SystemExit('Derleme işlenemedi: '+st)
    time.sleep(60)
if not build: raise SystemExit('Derleme 70 dakikada işlenmedi')
bid=build['id']
# 2) ihracat uyumu (şifreleme yok)
if build['attributes'].get('usesNonExemptEncryption') is None:
    patch(f'/builds/{bid}',{'data':{'type':'builds','id':bid,'attributes':{'usesNonExemptEncryption':False}}})
# 3) test bilgileri (Malazgirt'ten iletişim bilgisi kopyala)
src=get('/apps',**{'filter[bundleId]':os.environ['KAYNAK_BUNDLE']})['data']
if src:
    try:
        sd=get(f"/apps/{src[0]['id']}/betaAppReviewDetail")['data']['attributes']
        md=get(f'/apps/{APP}/betaAppReviewDetail')['data']
        at={k:sd.get(k) for k in ('contactFirstName','contactLastName','contactPhone','contactEmail')}
        at.update({'demoAccountRequired':False,'notes':'Tek kişilik, çevrimdışı tır simülasyonu (rüzgâr türbini lojistiği). Hesap/giriş yok. Sağda GAZ ve FREN pedalları, solda direksiyon okları. İlk 3 sefer ücretsiz.'})
        patch(f"/betaAppReviewDetails/{md['id']}",{'data':{'type':'betaAppReviewDetails','id':md['id'],'attributes':at}})
    except Exception as e: print('iletişim kopyalanamadı:',e)
    try:
        sl=get(f"/apps/{src[0]['id']}/betaAppLocalizations")['data']
        ml={x['attributes']['locale']:x for x in get(f'/apps/{APP}/betaAppLocalizations')['data']}
        for s in sl:
            loc=s['attributes']['locale']; a={'feedbackEmail':s['attributes'].get('feedbackEmail'),'description':'Kervan Yolu: tırla limandan rüzgâr sahasına kule, kanat, nasel ve yedek parça taşı; dört bölge, kanat kaldırıcı, kar zinciri, yan rüzgâr, forklift, drone ile hasar tespiti, 1923 sefer.'}
            if loc in ml: patch(f"/betaAppLocalizations/{ml[loc]['id']}",{'data':{'type':'betaAppLocalizations','id':ml[loc]['id'],'attributes':a}})
            else: post('/betaAppLocalizations',{'data':{'type':'betaAppLocalizations','attributes':dict(a,locale=loc),'relationships':{'app':{'data':{'type':'apps','id':APP}}}}})
    except Exception as e: print('yerelleştirme kopyalanamadı:',e)
# 4) "Neyi test etmeli"
for loc,txt in [('tr','YENİ (52, 1.1.2): Kökten katı dünya: sahnedeki her bina, direk, ağaç, pompa, kulübe, vinç ve kule kendiliğinden katı; tır ve forklift hiçbirinin içinden geçmiyor. Sahadan acil çağrılar: ilk teslimattan sonra izin istenir, oyun kapalıyken "türbin durdu, yedek parça bekleniyor" gibi bildirimler gelir, dokununca +%25 primli acil sefer açılır (Ayarlar\'dan kapatılır). Akaryakıt halkası kanopi direğinden uzaklaştırıldı. (50): Tren de katı cisim: tır trenin içinden geçemez; tır geçitteyken tren gelirse acil fren yapar, değip durur, yol açılınca devam eder. Trafik araçları, eskort ve polis aracı da artık katı. Yüklü dorse tam genişliğiyle sayılıyor. (49, 1.1.1): 48 ile aynı, App Store 1.1.1 güncellemesi için. (48): Genel katı cisim kuralı: tır, dorse, forklift, yerdeki kasalar ve istif yükleri birbirinin içinden geçmez; taşınan kasa yerdeki kasanın üstünden geçer, çatal kasanın altına girer. (47): Forklift yerdeki kasaların içinden geçmiyor; taşınan kasa da öteki kasalara çarpıyor. (46): Ceplerden önce yol kenarında mavi P levhası: AKARYAKIT, KANTAR ya da ZİNCİR TAKMA ve cebe kalan mesafe. (45): Ankraj kafesi artık bir sonraki türbinin temel çukuruna iniyor, montajdan sonra beton temel ve ankraj civataları görünüyor. Zincir cebi şantiye girişine çakışmıyor; cebi kaçıran, cebin hizasını geçince yolda zincir takabiliyor. Dil ekranında ENGLISH yazısı düzeldi. (44): Yol artık arazinin dalgalarını izlemiyor; dağ yollarında tırın asfalta gömülüp çıkması düzeldi. Kanat ve kule gibi uzun yüklerde cebe tam girmek gerekmez, cebin hizasında yolun sağına çekip durmak yeter. Forklift tırın ve dorsenin içinden geçemiyor. (43): Her teslimattan sonra vinç işi: türbine takılacak parça montajla takılır (kule, nasel, göbek, kanat; ankraj kafesi temel çukuruna indirilir), takılamayacak yük vinçle istif sahasına indirilir, indirme primi var. Serbest sürüşte de vinç var (primsiz). (42): Yol düzenleme bedelleri navluna oranlandı: planlı düzenleme navlunun en çok yüzde 12si, acil ekip tek seferde en çok yüzde 5i, toplamda yüzde 12si (fazlasını yatırımcı öder). Etüt büyük engelleri (turuncu) her zaman raporlar; deneme sürüşü yapılmazsa yalnız küçük engeller kaçabilir. Engelde, hemzemin geçitte ve geri manevrada beklenen süre teslim süresinden sayılmaz. (41): Yol kenarı cepleri: akaryakıt, kantar ve zincir takma artık yolun ortasında değil; sağdaki asfalt cebe girilip yapılır, sonra ana yola geri çıkılır. Cepte kesikli çizgi, cebin içindeki direkler kaldırıldı, kantar kulübesi dış tarafa alındı. (40): Ağaçlar gerçek takvime göre: eylül–kasım yapraklı ağaçlar sararıp kızarır. Montajı istersen operatöre bırakabilirsin (primsiz). (39): Deneme sürüşü seferi (menüde kariyer sekmesinde; boş, uzatılmış dorseyle engelleri işaretle, prim al; yapılmazsa etüt bazı engelleri kaçırır). 80 m kanat sınıfı ve alçak uç çerçevesi (kabloların altından geçer, en çok 40 km/sa). Hemzemin geçit: tren, bariyer, dur çizgisi, ceza (Marmara, İç Anadolu, Trakya, Kapadokya). Dağ sahalarında eskort yönlendirmeli geri manevra. Teslimden sonra vinçle montaj: kule 4 segment, nasel, 3 kanat; türbin sahada yükselir, rotor döner. Etüde dolgu ve toprak birikintisi. (38): Karşı trafik gerçekçi yol veriyor: düz yolda araç bankete yanaşıp dörtlüyle durur, tarlaya girmez; kanat seferinde eskort karşı aracı virajdan önce durdurur (kanat ucu karşı şeridi süpürür), dar virajda cepte bekletir; telsiz bunu söyler. (37): Etüt gerçek rapor düzeninde: güzergâh başına 13 engel, çoğu turuncu; kanat ucu tarama alanı (son yükseklik en çok 1,5 m), virajda yanal eğim, tümsekte bom sürtmesi, otobüs durağı ve çardak, köyde alçak kablolar, geçişte elektrik kesintisi. Yol işlerini yatırımcı öder, nakliyeci yüzde 10 koordinasyon payı verir; acil ekip yüzde 30. Kantar fişinde gerçekçi konvoy ağırlığı ve aks yükleri (kanat 28,5 t, toplam yaklaşık 76 t, aks hattı başına 11,4 t). (36): Güzergâh etüdü ve deneme sürüşü: kanat, kule ve nasel seferinde engeller dört renkle (yeşil, sarı, turuncu, kırmızı) raporlanır; dal budama, levha taşıma, kablo yükseltme, yol genişletme, OG direği deplase; düzenlenmeyen engel hasar ya da durma demek, acil ekip iki kat pahalı. Saha yolu: tekerlek izli çakıl, ortada çamur şeridi, kar yığınları, menfez, yol ver ve kaygan yol levhaları, viraj okları, köy yön levhası, söğütler, iletim hattı ve GSM direkleri. Sivas yaylasında eriyen kar lekeleri. (35): Eskort, polis aracı ve Malaklı artık kesintisiz akıcı hareket ediyor; karşıdan gelen araca değince araç kaybolmuyor, dörtlü yakıp duruyor, üstünde kırmızı işaret çıkıyor ve uyarı hangi araç olduğunu ve hangi tarafta kaldığını söylüyor; kanat ucuna göre daha doğru temas; çarpışmada titreşim. (34): Kayıt iCloud ile cihazlar arasında eşitlenir (telefon değişince kaldığın yerden); Kapadokya yolunda Malaklı çoban köpeği sürünün yanından tıra eşlik eder; App Store dil listesinde Türkçe. (33): Eskort aracında gerçek LED tepe lambası ve direkli DİKKAT GENİŞ YÜK levhası; polis ve jandarma aracı yeni sedan gövdeyle, mavi kırmızı LED lamba. (32): Dört yeni bölge: Çanakkale (Karabiga Limanı, zeytinlikler), Hatay (İskenderun Limanı, Belen Geçidi, narenciye bahçeleri, sert rüzgâr), Karadeniz (Trabzon Limanı, Çaykara yaylası, çay bahçeleri, serender, sis ve kar), Kapadokya (Mersin Limanı, peri bacaları, Erciyes). Köylerde el sallayan köylüler ve çay masası. (31): Sefer evrakında GÜZERGÂHI DRONE İLE KEŞFET: yol baştan sona uçulur; viraj, köy, enerji hattı, kantar, akaryakıt, zincir ve çamur işaretlenip mini haritada kalır. (30): FİRMA sekmesi: firma adı, kasa, ekipman (teleskopik dorse, blade lifter, SPMT, ek tır), kredi ve faiz, şoförler, beceriler; 10 türbinlik RES projesi (vinç bekleme bedeli, final sahnesi). (29): Trafik araçları baştan çizildi: sedan, hatchback, SUV, çift kabin pikap, dolmuş, şehirlerarası otobüs, tır, traktör; Türk plakaları, yeni jantlı tekerlekler, fren lambası, gece farı, yol verirken dörtlü, dönen ön teker, frende öne yatma. (28): Yağmur (gri gökyüzü, ıslak yol, uzayan fren, kabin görünümünde silecek, yağmur sesi; serbest modda Hava seçimi), stabilize saha yolu, yağmur sonrası çamur ve dozerle çekme. (27): İzin şartları: Marmara ve Trakyada kanat ve kule yalnız gece; özel yükte hız yerleşimde 30, dışında 50; kanat ve nasel seferlerinde önde trafik polisi ya da jandarma refakati. (26): Akaryakıt: yolda turuncu YAKIT halkası ve 1 km önceden uyarı; depo dolu değilse her zaman YAKIT AL (tesis sahasına da girilebilir); yakıt aldıktan sonra MOLA VER çıkar. Kantarda mavi halka. Telsiz artık gerçek trafiğe göre konuşuyor. (24): Limandan çıkan her yükte belge kontrolü: sefer modunda her işte çıkış belgesi ve irsaliye (ağır yükte izinler, ithal ve konteynerde gümrük muayenesi); serbest modda da limandan her yüklemede gümrük ve belgeler (bedelsiz). (23): Akaryakıt ve dinlenme tesisi baştan yapıldı: uzaktan görünen ışıklı fiyat direği, kanopi ve pompa adaları, market, tır parkı, 500 m ve 200 m önceden yön levhaları, haritada yakıt simgesi; tesis ve kantar zemini düzlendi. (22): Korna (H) ve dörtlü (Z) düğmeleri, otomatik sinyal, eskort telsiz anonsları, Mr. Anduv! FM yol ve hava bülteni. (20): Fotoğraf modu (molada FOTOĞRAF MODU ya da F), yakıt (dinlenme tesisinde YAKIT AL) ve ağır yükler için kantar. (19): Nasel, göbek, güç aktarma, ankraj ve konteyner yükleri gerçekçi spanzet ve zincirle bağlanıyor (kafes görüntüsü kalktı); nasel soğutucu ve korkuluklu, göbekte kanat flanş kapakları; aktarma sahasında teleskopik bomlu vinç, halat ve kanca. (18): Grafik yenilendi: gerçekçi ışık ve malzemeler, daha aydınlık gece, 22 m kule segmenti (flanş, koruma kapağı, beşik, spanzet), yuvarlak hatlı kabin, dikey ekranda üst yazı düzeltildi. (17): Takograf (4,5 saat sürüş, dinlenme tesisinde 45 dk mola, ihlalde ceza) ve kanat seferinde 15 m/s üstü rüzgârda limanda bekleme. (16): Limanda gemiden tahliye, gümrük muayenesi, sefer evrakı (izin belgesi, kullanım bedeli, yol düzenlemesi protokolü) ve çıkış kapısı; Egede aktarma sahasında vinçle blade liftera aktarma; raporda kalem kalem masraf. (15): Uzun yükte (kanat, kule) arkada da eskort aracı. (14): Kanat taşıması gerçeğe uygun: 72 m kanat, uzayan dorse, uç çerçevesi, kendi dönen arka boji; Ege köyünde kanat kalkınca dorse içeri kayar. Virajlarda kanadın ucunun nereden geçtiğine bakın. Mr. Anduv! FM. Ana menüde açılış teması (Kervan Dönüyor); kabinde FM düğmesiyle radyo: dokun aç/kapat, basılı tut sonraki şarkı. 12 şarkı internetsiz, internet varken 123 şarkının hepsi. Uyarı gelince müzik kısılıyor mu, başka uygulamadan dönünce müzik sürüyor mu, Ayarlardaki müzik sesi çalışıyor mu bakın. Dört bölge: Marmara, Ege (dar köy sokağında kanat kaldırıcı, ardından enerji hattı), İç Anadolu/Sivas (buzlu yol, mavi halkada kar zinciri), Trakya (yan rüzgâr ve rüzgâr göstergesi). Yeni yükler: nasel, hub, güç aktarma, ankraj kafesi, malzeme konteyneri. Yeni: hız sınırları ve EDS, karşı trafik ve sağ şerit kuralı, geniş yükte eskort aracı, üretici etiketleri ve saha tabelaları. Serbest Sürüş\'te bölge seç; uyarıların ne yapacağını söyleyip söylemediğine, yatay ve dikey ekrana bakın.'),('en-US','NEW (52, 1.1.2): Solid world at the root: every building, pole, tree, pump, booth, crane and tower is solid by default; neither the truck nor the forklift passes through anything. Urgent site calls: after your first delivery the game asks, then sends local notifications like "turbine down, spare part needed"; tapping opens an urgent haul with a 25 percent bonus (switch off in Settings). (50): The train is solid too: the truck cannot drive through it, and if the truck is on the crossing the train brakes hard, touches and waits until the way is clear. Traffic, escort and police cars are solid as well. A loaded trailer counts with its full width. (49, 1.1.1): Same as 48, for the App Store 1.1.1 update. (48): General solid-body rule: truck, trailer, forklift, crates and laydown loads never pass through each other; a raised crate clears the ones on the ground and the forks slide under a pallet. (47): The forklift no longer drives through crates on the ground, and the carried crate bumps into the others. (46): Blue P signs before each lay-by show FUEL, WEIGH STATION or CHAIN-UP AREA and the distance. (45): The anchor cage now goes into the next turbine foundation pit; after assembly the concrete foundation and anchor bolts appear. The chain-up lay-by no longer overlaps the site entrance; if you miss it you can fit chains on the road once past it. Fixed the ENGLISH label on the language screen. (44): The road no longer follows terrain ripples, so the truck no longer sinks into the asphalt on mountain roads. With long loads (blades, tower sections) pulling over to the right beside the lay-by is enough. The forklift can no longer drive through the truck and trailer. (43): Crane work after every delivery: parts that fit the turbine are assembled (tower, nacelle, hub, blades; the anchor cage goes into the foundation pit), other loads are craned onto the laydown area for an offload bonus. Free drive gets the crane too (no bonus). (42): Road work costs now scale with the freight fee: planned works at most 12 percent, an emergency crew at most 5 percent each and 12 percent in total (the investor covers the rest). The survey always reports major (orange) obstacles; without a dummy run only small ones can be missed. Time spent stopped at obstacles, level crossings and the reverse manoeuvre no longer counts against the delivery time. (41): Roadside lay-bys: fuel, weigh station and chain-up are no longer done in the middle of the road; pull into the paved lay-by on the right, then rejoin the road. (40): Trees follow the real calendar: broadleaf trees turn yellow and red from September to November. You can leave the assembly to the crane operator (no bonus). (39): Dummy run job (career tab; empty extended trailer, mark obstacles, earn a bonus; without it the survey misses some obstacles). 80 m blade class and low tip frame (passes under cables, max 40 km/h). Level crossing: train, barriers, stop line, fine. Escort guided reverse manoeuvre on mountain sites. Crane assembly after delivery: 4 tower sections, nacelle, 3 blades; the turbine rises on site and the rotor turns. Fill and soil heap obstacles. (38): Oncoming traffic yields realistically: on straights cars pull onto the shoulder with hazards on instead of driving into the field; on blade jobs the escort holds oncoming cars before bends where the blade tip sweeps the other lane, or in a pocket at tight bends; the radio says so. (37): Survey follows a real report layout: 13 obstacles per route, mostly orange; blade-tip sweep zone (final height at most 1.5 m), cross slope in bends, boom scraping on crests, bus stop and shelter, low village cables, power cut during the pass. The investor pays for road works, the carrier pays a 10 percent share; emergency crew 30 percent. Weigh ticket shows realistic convoy weight and axle loads (blade 28.5 t, about 76 t total, 11.4 t per axle line). (36): Route survey and dummy run: obstacles on blade, tower and nacelle jobs are colour-coded green, yellow, orange, red; trim branches, move signs, raise cables, widen roads, relocate MV poles; unfixed obstacles mean damage or a stop, and an emergency crew costs double. Site road: rutted gravel with a mud strip, snow banks, culvert, give way and slippery road signs, chevrons, village sign, willows, power line and GSM masts. Patchy melting snow on the Sivas plateau. (35): Escorts, police car and the shepherd dog now move smoothly; when your load touches an oncoming vehicle it stays, puts on hazards and gets a red marker, and the warning names the vehicle and side; more accurate blade contact; haptic feedback on crashes. (34): Progress syncs across devices with iCloud; a Malakli shepherd dog runs alongside the truck on the Cappadocia road; Turkish listed as an app language. (33): Escort pickup gets a real LED light bar and a framed WIDE LOAD sign; police and gendarmerie cars use the new sedan body with a blue and red LED bar. (32): Four new regions: Canakkale (Karabiga port, olive groves), Hatay (Iskenderun port, Belen Pass, citrus orchards, strong winds), Black Sea (Trabzon port, Caykara highland, tea gardens, granaries, fog and snow), Cappadocia (Mersin port, fairy chimneys, Mount Erciyes). Waving villagers and a tea table in villages. (31): SURVEY THE ROUTE BY DRONE in the trip papers: fly the whole road; bends, village, power line, weigh station, fuel, chains and mud are marked and stay on the minimap. (30): COMPANY tab: name, cash, equipment (telescopic trailer, blade lifter, SPMT, extra truck), loans and interest, drivers, skills; 10 turbine wind farm project (crane standby charges, finale). (29): Traffic redrawn: sedan, hatchback, SUV, double cab pickup, minibus, intercity coach, truck, tractor; Turkish plates, new wheels, brake lights, night headlights, hazards when yielding, steering front wheels, nose dive on braking. (28): Rain (grey sky, wet road, longer braking, wipers in cab view, rain sound; Weather choice in free mode), gravel site road, mud after rain and dozer tow. (27): Permit conditions: blades and towers move only at night in Marmara and Thrace; abnormal loads at 30 km/h in built-up areas and 50 outside; police or gendarmerie escort leads blade and nacelle convoys. (26): Fuel: orange FUEL ring on the road and an early heads-up; REFUEL whenever the tank is not full (you can also drive onto the forecourt). Blue ring at the weigh station. Escort radio now reacts to real traffic. (24): Papers checked for every load leaving the port: release order and waybill on every career job (permits for heavy loads, customs inspection for imports and containers); free mode now goes through customs and papers on every port pickup (no fees). (23): Fuel and rest area rebuilt: lit price pylon visible from afar, canopy and pump islands, shop, truck park, signs 500 m and 200 m ahead, fuel icon on the map; station and weigh station sit on level ground. (22): Horn (H) and hazard (Z) buttons, auto turn signals, escort radio calls, Mr. Anduv! FM road and weather bulletins. (20): Photo mode (PHOTO MODE in pause or F), fuel (REFUEL at the rest area) and weigh station for heavy loads. (19): Nacelle, hub, drivetrain, anchor cage and container loads now secured with real ratchet straps and chains (no more cage look); nacelle cooler and rails, hub blade-flange covers; telescopic crane with cable and hook at the transfer yard. (18): Graphics overhaul: realistic lighting and materials, brighter nights, 22 m tower section (flanges, end covers, saddles, ratchet straps), rounded cab, portrait banner fix. (17): Tachograph (4.5 h driving, 45 min break at the rest area, fine if broken) and blade jobs waiting at port in winds over 15 m/s. (16): Ship discharge, customs inspection, trip permits and the port exit gate; blade lifter transfer by crane on the Aegean route; itemised costs in the report. (15): Rear escort vehicle for long loads (blade, tower). (14): Realistic blade haul: 72 m blade, extendable trailer, tip frame, self-steering rear bogie; the trailer retracts when the blade is lifted in the Aegean village. Mr. Anduv! FM. Opening theme on the main menu; in-cab radio via the FM button: tap on/off, hold for next song. 12 songs offline, all 123 online. Four regions: Marmara, Aegean (blade lifter in a narrow village street, then a power line), Central Anatolia/Sivas (icy road, snow chains in the blue ring), Thrace (crosswind and wind gauge). New loads: nacelle, hub, drive train, anchor cage, material container. New: speed limits and speed cameras, oncoming traffic and keep-right rule, escort vehicle for wide loads, manufacturer labels and site signs. Pick a region in Free Drive; check that every warning tells you what to do, in landscape and portrait.')]:
    ex=[x for x in get(f'/builds/{bid}/betaBuildLocalizations')['data'] if x['attributes']['locale']==loc]
    if ex: patch(f"/betaBuildLocalizations/{ex[0]['id']}",{'data':{'type':'betaBuildLocalizations','id':ex[0]['id'],'attributes':{'whatsNew':txt}}})
    else: post('/betaBuildLocalizations',{'data':{'type':'betaBuildLocalizations','attributes':{'locale':loc,'whatsNew':txt},'relationships':{'build':{'data':{'type':'builds','id':bid}}}}})
